"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import {
  FaHome,
  FaCompass,
  FaComment,
  FaPhone,
  FaBell,
  FaUser,
  FaSignOutAlt,
} from "react-icons/fa";

export default function Sidebar() {
  const { user, logout } = useAuth();
  const router = useRouter();

  return (
    <aside className="w-64 bg-gray-900 text-white flex flex-col p-4 min-h-screen">
      <div
        className="text-3xl font-bold text-blue-400 mb-8 cursor-pointer"
        onClick={() => router.push("/dashboard")}
      >
        Huddle
      </div>

      <nav className="flex flex-col gap-6 text-lg">
        <Link
          href="/dashboard"
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaHome /> Home
        </Link>
        <Link
          href="/explore"
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaCompass /> Explore
        </Link>
        <Link
          href="/messages"
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaComment /> Messages
        </Link>
        <Link
          href="/call"
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaPhone /> Call
        </Link>
        <Link
          href="/notifications"
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaBell /> Notifications
        </Link>
        <Link
          href={`/profile/${user?.id}`}
          className="hover:text-blue-400 flex items-center gap-3"
        >
          <FaUser /> Profile
        </Link>
      </nav>

      <button
        onClick={logout}
        className="mt-auto bg-red-600 hover:bg-red-700 text-white font-semibold px-4 py-2 rounded flex items-center gap-2"
      >
        <FaSignOutAlt /> Logout
      </button>
    </aside>
  );
}
