"use client";

import { useEffect, useState } from "react";
import AppLayout from "@/components/AppLayout";
import api from "@/services/api";
import { useRouter } from "next/navigation";
import { FaPhone, FaVideo, FaCircle } from "react-icons/fa";
import { useSocket } from "@/contexts/SocketContext";
import { useAuth } from "@/contexts/AuthContext";

export default function CallPage() {
  const { user } = useAuth();
  const socket = useSocket();
  const [users, setUsers] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);

  useEffect(() => {
    const fetchUsers = async () => {
      try {
        const res = await api.get("/api/users");
        setUsers(res.data.users || []);
      } catch (err) {
        console.error("❌ Failed to fetch users:", err.message);
      }
    };

    fetchUsers();
  }, []);

  useEffect(() => {
    if (!socket) return;

    const handleOnlineUsers = (ids) => {
      setOnlineUsers(ids);
    };

    socket.on("user_online", handleOnlineUsers);

    return () => {
      socket.off("user_online", handleOnlineUsers);
    };
  }, [socket]);

  const isOnline = (id) => onlineUsers.includes(id);

  const handleCall = (userId, type) => {
    if (!socket || !user || !isOnline(userId)) return;

    const offer = {
      type: type,
      sdp: "dummy-offer", // You can replace with actual WebRTC offer if needed
    };

    socket.emit("call_user", {
      to: userId,
      offer,
    });

    alert(`Calling ${userId} via ${type}...`);
  };

  return (
    <AppLayout>
      <div className="space-y-6">
        <h1 className="text-2xl font-bold mb-4">Start a Call</h1>
        <ul className="space-y-4">
          {users.length === 0 ? (
            <p>No users found.</p>
          ) : (
            users
              .filter((u) => u.id !== user?.id)
              .map((u) => (
                <li
                  key={u.id}
                  className="bg-white text-gray-800 p-4 rounded shadow flex justify-between items-center"
                >
                  <div className="flex items-center gap-3">
                    {u.avatar && (
                      <img
                        src={u.avatar}
                        alt={u.username}
                        className="w-10 h-10 rounded-full"
                      />
                    )}
                    <div className="flex flex-col">
                      <span className="font-medium">@{u.username}</span>
                      {isOnline(u.id) && (
                        <span className="text-green-500 text-xs flex items-center gap-1">
                          <FaCircle className="text-green-500" size={8} />
                          Online
                        </span>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-3">
                    <button
                      disabled={!isOnline(u.id)}
                      onClick={() => handleCall(u.id, "audio")}
                      className={`p-2 rounded text-white ${
                        isOnline(u.id)
                          ? "bg-blue-500 hover:bg-blue-600"
                          : "bg-gray-300 cursor-not-allowed"
                      }`}
                      title="Voice Call"
                    >
                      <FaPhone />
                    </button>
                    <button
                      disabled={!isOnline(u.id)}
                      onClick={() => handleCall(u.id, "video")}
                      className={`p-2 rounded text-white ${
                        isOnline(u.id)
                          ? "bg-green-500 hover:bg-green-600"
                          : "bg-gray-300 cursor-not-allowed"
                      }`}
                      title="Video Call"
                    >
                      <FaVideo />
                    </button>
                  </div>
                </li>
              ))
          )}
        </ul>
      </div>
    </AppLayout>
  );
}
